    checklist: ["동양 윤리 5대 학자 (공자·맹자·순자·노장·불교) 핵심 개념 정리?","서양 윤리 6대 학자 (소크라테스·플라톤·아리스토텔레스·칸트·공리주의·롤스) 핵심 정리?","빈출 6핵심 개념 (인·사단·정언명령·공리·정의·중용) 외우기?","의무론 (칸트) vs 결과론 (공리주의) 차이 이해?","매주 5문항 + 1:1 첨삭?"],
    checklistTitle: "윤리 사상 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "칸트의 정언명령이 뭐예요?", a: "표준 3가지 형식이 답이에요. (1) 보편 법칙 정식: \"네 의지의 준칙이 보편 법칙이 되도록 행동하라\". (2) 인간성 정식: \"인간을 단순 수단이 아닌 목적으로 대하라\". (3) 자율성 정식: \"네 의지가 보편적으로 입법한다고 여기고 행동하라\". 핵심: 의무론·동기 우선·자율성. 공리주의 (결과 우선)와 정반대 관점. 빈출 함정·매주 정리 + 1:1 첨삭이 1·2등급의 비밀이에요."},
      {q: "공리주의와 의무론 차이?", a: "표준 차이가 답이에요. (1) 공리주의: 결과론·\"최대 다수의 최대 행복\"·결과 우선·벤담 (양적) / 밀 (질적). (2) 의무론 (칸트): 동기 우선·정언명령·인간을 목적으로·자율성. 같은 행위라도 평가 다름. 예: 거짓말 → 공리주의 (결과 좋으면 OK) vs 칸트 (절대 안 됨). 매 사례 양 관점 + 1:1 첨삭이 1·2등급의 결정적 비밀이에요."},
      {q: "공자·맹자·순자 차이?", a: "표준 3가지가 답이에요. (1) 공자: 인 (仁)·예 (禮)·정명. 유가의 시조·인간다움 강조. (2) 맹자: 성선설 (인간 본성 선)·사단 (측은·수오·사양·시비)·왕도 정치. (3) 순자: 성악설 (인간 본성 악)·예치 (예로 다스림)·후천적 노력. 빈출 함정. 매주 3학자 핵심 개념 + 1:1 첨삭이 답이에요."},
      {q: "롤스의 정의론이 뭐예요?", a: "표준 3원칙이 답이에요. (1) 무지의 베일: 자신의 사회적 위치 모르는 상태에서 정의 결정. (2) 평등한 자유 원칙: 모두에게 동등한 기본 자유. (3) 차등 원칙: 사회·경제적 불평등은 최소 수혜자에게 이익이 될 때 정당. 자유주의 + 분배 정의. 칸트 영향. 빈출 학자·매주 정리 + 1:1 첨삭이 1·2등급의 비밀이에요."},
    ],
